function demoMain(idx,label){
  var ops=[["alloc A","alloc B","free A","free A"],["alloc X","free X","use X"],["alloc P","alloc Q","free P"],["alloc M","free M","free M"]];
  var live={},issues=[];var o=ops[idx%ops.length];
  o.forEach(function(op){var p=op.split(" ");if(p[0]=="alloc")live[p[1]]=1;
    else if(p[0]=="free"){if(!live[p[1]])issues.push("double-free "+p[1]);else delete live[p[1]];}
    else if(p[0]=="use"){if(!live[p[1]])issues.push("use-after-free "+p[1]);}});
  for(var k in live)issues.push("leak "+k);
  return "["+label+"] ops: "+o.join(", ")+" => "+(issues.length?issues.join("; "):"no issues");
}

